import{_ as o,o as d,c,aj as s}from"./chunks/framework.CX3tclo0.js";const h=JSON.parse('{"title":"把 30B 全模态模型改造成全双工语音助手：十天实测、工程拆解与自我推翻","description":"围绕 Qwen3-Omni-30B-A3B 构建中文全双工语音交互系统的完整复盘：梳理十天五个阶段的真实演进路径，拆解因果基线、亚秒级工程与受控审计发现，并给出集齐全部优化手段的从零重训配方。","frontmatter":{"publish":true,"title":"把 30B 全模态模型改造成全双工语音助手：十天实测、工程拆解与自我推翻","date":"2026-11-26T00:00:00.000Z","category":"InteractionModel","tags":["全双工语音","Qwen3-Omni","因果训练","GRPO","系统工程"],"description":"围绕 Qwen3-Omni-30B-A3B 构建中文全双工语音交互系统的完整复盘：梳理十天五个阶段的真实演进路径，拆解因果基线、亚秒级工程与受控审计发现，并给出集齐全部优化手段的从零重训配方。"},"headers":[],"relativePath":"blog/posts/qwen3-omni-full-duplex-journey.md","filePath":"blog/posts/qwen3-omni-full-duplex-journey.md"}'),n={name:"blog/posts/qwen3-omni-full-duplex-journey.md"};function a(t,e,l,r,p,i){return d(),c("div",null,[...e[0]||(e[0]=[s(`<h2 id="问题从哪里开始" tabindex="-1">问题从哪里开始 <a class="header-anchor" href="#问题从哪里开始" aria-label="Permalink to &quot;问题从哪里开始&quot;">​</a></h2><p>让大模型实现全双工语音对话，往往被简化成一句话：给语音模型接一个低延迟的端点检测（VAD），说完就答，插话就停。但在真实中文对话里，系统必须同时答对四道题：用户说完时及时开口、句中换气或对旁人说话时不抢话、助手正在播报时遇到真插话立刻停播，以及停播后按用户耳朵实际听到的位置决定续讲、改答还是静默。</p><p>过去十天，我围绕 <code>Qwen3-Omni-30B-A3B-Instruct</code> 推进中文全双工交互系统。整个过程累计运行约两百九十次分布式训练与评测作业、消耗一千两百余 PPU 卡时，并没有写成一条单调上升的曲线，反而更像连续推翻假设的排雷记录：早期探针被时钟捷径骗过，外挂读出头撞上跨会话校准墙，音频小样微调失效后倒逼出纯因果文本账本方案；工程侧把首词延迟压到 <code>52.39 ms</code>、接上回声消除与声纹锁之后，一次严苛的审计又刺破了对称窗口指标的虚高，迫使训练目标回到冻结前端与排序分离。</p><p>下面先给出这十天实际走过的全景演进路径，再拆解关键踩坑、系统架构与受控审计，最后总结一套如果从零重训、一次用齐全部验证过优化手段的完整配方。</p><h2 id="一、全景路径-十天五个阶段的演进与转向" tabindex="-1">一、全景路径：十天五个阶段的演进与转向 <a class="header-anchor" href="#一、全景路径-十天五个阶段的演进与转向" aria-label="Permalink to &quot;一、全景路径：十天五个阶段的演进与转向&quot;">​</a></h2><p>项目最初并非直接做纯语音 80ms 状态机，而是从「视觉世界状态（JEPA）+ 多模态底座」出发，在一次次实测证伪中收缩聚焦，再沿全双工工程和因果训练一路推进的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Stage 0 · 11/16–11/17] 基底摸底与因果立规</span></span>
<span class="line"><span>  Qwen2.5-Omni(3B/7B) + V-JEPA2 + Duo 参照</span></span>
<span class="line"><span>  └─ 淘汰短窗伪增益与时钟捷径 -&gt; 切入 Qwen3-Omni 30B</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>[Stage 1 · 11/18–11/21] 冻结读出、小样微调与内容拐点</span></span>
<span class="line"><span>  0053 LoRA / E1 4096维读出 / 8族校准 / 软蒸馏</span></span>
<span class="line"><span>  └─ 关闭外挂校准与小样正文微调 -&gt; 冻结底座 + 因果文本账本</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>[Stage 2 · 11/22–11/23] 80ms FSM 主线与 A/B/C 消融</span></span>
<span class="line"><span>  Awaken 17词元 + clean-pool-v1 + 控制 GRPO + c2/c3 门控</span></span>
<span class="line"><span>  └─ 否决脏正例扩池(Plan B/C) -&gt; 锁定非对称守门员 Plan A</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>[Stage 3 · 11/23–11/24] 亚秒级工程与全双工三块拼图</span></span>
<span class="line"><span>  双卡增量 KV (TTFT 52ms) + AEC/声纹锁 + 1.47M 词面头</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>[Stage 4 · 11/24–11/25] 审计归零、归因对照与 Plan D v2</span></span>
<span class="line"><span>  严控 [0,+960ms] + 修 3 处评测 Bug + 3 组受控对照</span></span>
<span class="line"><span>  └─ 冻结前端 + Pairwise AUROC Margin (校验 AUROC 0.9786)</span></span></code></pre></div><p>把每个阶段的核心尝试、淘汰支线和保留下来的硬资产并排看，转向逻辑会更清楚：</p><table tabindex="0"><thead><tr><th>阶段</th><th>时间</th><th>核心探索</th><th>被否决/关闭的路线</th><th>沉淀下来的有效资产</th></tr></thead><tbody><tr><td><strong>Stage 0｜立规与选型</strong></td><td>11/16–11/17</td><td><code>Qwen2.5-Omni</code> 3B/7B 筛选、<code>V-JEPA2</code> 16 帧探测、<code>Duo</code> 32B 对照、<code>Qwen3-Omni</code> 原生流式解码</td><td>短窗口（3.75s）JEPA 探测、旧时钟捷径协议、<code>Duo</code> 视听支线</td><td>完整因果前缀契约、真实播放账本原则、FP32 独立声码解码（前缀 RMS 误差降 ~74x）</td></tr><tr><td><strong>Stage 1｜读出与内容破局</strong></td><td>11/18–11/21</td><td><code>0053</code> 动作 LoRA、MagicData 70→236 场扩量、E1 冻结音频塔 8 族校准、Awaken 15 折留一、中文听写软蒸馏与小样正文微调</td><td>外挂线性头 + 阈值校准（8 族全败）、小样本正文微调（<code>1/5</code>）、听写前端软蒸馏（<code>0/4</code>）</td><td>训练集 100% 拟合闸门、整场因果前向 <code>scene_forward</code>（~20x 加速）、<strong>冻结 30B + 双路因果 ASR 文字与账本</strong>（MagicData <code>5/5</code> / AliMeeting <code>6/7</code>）</td></tr><tr><td><strong>Stage 2｜80ms FSM 与消融</strong></td><td>11/22–11/23</td><td>接入 Awaken 80ms 17 词元 FSM、<code>clean-pool-v1</code> 因果 SFT、控制词元专属 GRPO、2–3 帧确认门控、<code>clean-pool-v2</code>（Plan B/C）扩池</td><td>纯 LoRA 冻前端（跨场 <code>SE R=0</code>）、未筛高重叠扩池 Plan B/C（<code>AUROC</code> 跌至 <code>0.8103</code>）、旧对称校准窗 <code>[-12,+12]</code></td><td><code>lr_audio_scale=0.25</code> 治愈中文乱码（<code>12/12</code>）、纯因果 <code>c2/c3</code> 确认门控（早抢 <code>-68.6%</code>）、非对称因果守门员协议</td></tr><tr><td><strong>Stage 3｜工程破秒与拼图</strong></td><td>11/23–11/24</td><td>双卡控制/内容解耦、异步增量 <code>DynamicCache</code>、端云 NLMS AEC + <code>WeSpeaker34</code> 声纹锁、<code>1.47M</code> 声学×词面联合头、实时浏览器试玩台</td><td>单卡全量重算链路、纯声学硬扛句中停顿与旁人说话</td><td><code>TTFT 52.39 ms</code> / <code>TTFA 412.94 ms</code>、26 字立停第 27 字续讲、AEC <code>ERLE 37.64 dB</code>、联合头 <code>Easy-Turn AUROC 0.6945</code>、20s 错题飞轮</td></tr><tr><td><strong>Stage 4｜审计纠偏与重塑</strong></td><td>11/24–11/25</td><td>核对原始 JSON、修 3 处评测 Bug、跑 <code>Baseline-GK</code> / M4 等预算 / Stage 5 纯声学对照、启动 <code>Plan D v2</code></td><td>宽口径 <code>±960ms</code> 计分、放开音频前端导致 <code>pad_acc</code> 塌陷的纯声学配方</td><td>严格 <code>[0,+960ms]</code> 验收口径、全套纠偏评测脚本、<strong>100% 冻结前端 + Pairwise AUROC 排序训练</strong>（校验 <code>se_vs_pad_auroc 0.9786</code>）</td></tr></tbody></table><h2 id="二、先把评测关进因果笼子" tabindex="-1">二、先把评测关进因果笼子 <a class="header-anchor" href="#二、先把评测关进因果笼子" aria-label="Permalink to &quot;二、先把评测关进因果笼子&quot;">​</a></h2><p>项目早期并不只看纯语音，还同时探索过 <code>Qwen2.5-Omni</code>（3B/7B）、<code>V-JEPA2</code> 视觉状态融合，以及 <code>Duo</code> 的分块交互思路。很快我们在两组探索里踩出了两类典型幻觉，也直接确立了后面贯穿全程的两条实验铁律。</p><h3 id="_2-1-短窗口探针与-时间捷径" tabindex="-1">2.1 短窗口探针与“时间捷径” <a class="header-anchor" href="#_2-1-短窗口探针与-时间捷径" aria-label="Permalink to &quot;2.1 短窗口探针与“时间捷径”&quot;">​</a></h3><p>在 <code>V-JEPA2</code> 试点中，我们在 13 段视频的 343 条因果观测上，用最近 16 帧（约 <code>3.75 s</code>）做冻结表征探测。表面上看，加入视觉表征与历史动作的 <code>JH</code> 分支将事件 F1 从 <code>0.0952</code> 提到了 <code>0.1667</code>；但两个对照实验立刻否定了这个结论：把 <code>Omni</code> 特征重复投影一次的等参数对照组（<code>OO</code>），以及故意打乱视觉时序的对照组（<code>JH_shuffle</code>），同样把条件 F1 从 <code>0.6957</code> 拉到了 <code>0.7213</code> 和 <code>0.7576</code>。窗口太短且缺少完整上下文历史时，模型很容易把局部统计波动当成视觉语义收益。</p><p>几乎在同一时间，动作探测线上暴露了更致命的问题：在早期的开发集上，一套只输入<strong>时间进度与当前播放状态</strong>、完全不看音频内容的基线，竟然拿到了 <code>68/68</code> 的准确率。模型根本没有学会判断用户是否说完，只是学会了数样本长度和固定切点位置。</p><h3 id="_2-2-两条底线-完整因果前缀与真实执行账本" tabindex="-1">2.2 两条底线：完整因果前缀与真实执行账本 <a class="header-anchor" href="#_2-2-两条底线-完整因果前缀与真实执行账本" aria-label="Permalink to &quot;2.2 两条底线：完整因果前缀与真实执行账本&quot;">​</a></h3><p>被“时间捷径”教训之后，项目冻结了三条不可妥协的输入与数据规则：</p><ol><li><strong>完整因果前缀</strong>：任何判断与生成只能读取从已知会话起点到当前决策时刻真正到达的输入流，严禁任何未来帧；预处理器截断或超上下文窗口必须显式隔离，不能静默裁掉前文后仍称基线。</li><li><strong>一等公民的设备账本（<code>ExecutionLedger</code>）</strong>：助手在流式生成中经历“生成、提交、播放器播出、被打断停止、未播取消”五个物理阶段。模型在上下文里看到的不能是“我生成了什么”，而必须是播放器回执确认“用户实际听到了哪一个字、还有多少字没播出来”。</li><li><strong>真人原声与合成音频隔离</strong>：训练与主验收严格只使用来源、许可与说话人切分可核实的真人多轨语料，明确剔除外部基准包里的 TTS 合成样本（仅作隔离诊断，不混入主结论）。</li></ol><p>真实设备测试很快验证了 <code>ExecutionLedger</code> 的必要性。在一段 <code>167.9 s</code> 的长程真实录音里，系统在前一轮尚未出声时被用户追问“为什么不说话”。没有可读执行账本的生成器，即便被强制路由为“新回答”，依然会沿着旧历史复读开场白；只有把 <code>turn#1 (cancelled) 已播 0/15 字</code> 显式写进因果上下文后，模型才稳定回答“我刚刚在处理您的问题，现在开始回答”，消除陈旧续讲错乱。</p><h2 id="三、三条走不通的路-分别指明了什么" tabindex="-1">三、三条走不通的路，分别指明了什么 <a class="header-anchor" href="#三、三条走不通的路-分别指明了什么" aria-label="Permalink to &quot;三、三条走不通的路，分别指明了什么&quot;">​</a></h2><p>在正式收敛到最终架构之前，我们先后把三条看似合理的技术路线跑到了明确证伪。</p><h3 id="_3-1-冻结音频塔-外挂读出头-跨场尺度墙" tabindex="-1">3.1 冻结音频塔 + 外挂读出头：跨场尺度墙 <a class="header-anchor" href="#_3-1-冻结音频塔-外挂读出头-跨场尺度墙" aria-label="Permalink to &quot;3.1 冻结音频塔 + 外挂读出头：跨场尺度墙&quot;">​</a></h3><p>全模型 30B 前向单步最短也要 <code>186 ms</code> 左右，很自然的想法是冻结 <code>Qwen3-Omni</code> 的音频编码塔，在 4096 维完整前缀表征上训练轻量线性分类头，再配合阈值或校准规则做实时决策。我们在 15 场真人对话（476 个时间格）上做了系统验证：</p><ul><li><strong>第一个坑是欠拟合伪证</strong>：在封存的正则化系数 <code>λ=0.01</code> 下，全部 8 种训练目标都在留一交叉验证上表现为“模型经常沉默”（<code>6/15</code> 及时、<code>9/15</code> 全场不开口）。检查训练集拟合情况才发现，在 <code>λ=0.01</code> 下训练集准确率只有 <code>97.27%</code>，32 个合法开口格里有 13 个分数根本没越过零点。当把 <code>λ</code> 降到 <code>0.0003</code>，<code>15/15</code> 折全部通过训练集 100% 拟合门，及时数立刻升到 <code>8–9/15</code>。由此确立了一条硬约束：<strong>每次训练必须先过训练集拟合门，否则任何“配方无效”的结论都只是欠拟合的产物。</strong></li><li><strong>第二个坑是跨场尺度不可校准</strong>：过门之后，如果我们允许每场会话各自取最优阈值（rank-1 oracle），及时率上限高达 <strong><code>14/15</code></strong>。这说明“用户是否说完”的信号确实已经编码在音频塔表征里；但只要换回部署态的单一全局阈值，成绩立刻掉回 <code>8–9/15</code>（<code>combo</code> 目标为 <code>9</code> 场及时、<code>0</code> 早抢；纯逐点 BCE 为 <code>8</code> 场及时、<code>1</code> 早抢）。把文献中常用的 8 族校准机制（含 cohort 归一化与保形分位预测）全部跑完一遍后，oracle 最高只有 <code>3/15</code>，迟滞阈值在 26 种组合下与单阈值结果完全重合。</li></ul><p>结论很明确：冻结声学表征本身缺少跨会话的绝对尺度对齐，必须回到带指令上下文的 <code>Thinker</code> 主干里解决决策问题。</p><h3 id="_3-2-小样本微调内容-vs-冻结底座接因果文字历史" tabindex="-1">3.2 小样本微调内容 vs 冻结底座接因果文字历史 <a class="header-anchor" href="#_3-2-小样本微调内容-vs-冻结底座接因果文字历史" aria-label="Permalink to &quot;3.2 小样本微调内容 vs 冻结底座接因果文字历史&quot;">​</a></h3><p>解决了“什么时候开口”之前，我们还试过直接提升“开口后答得好不好”。这里出现了一个非常反直觉的对照结果：</p><table tabindex="0"><thead><tr><th>方案</th><th>训练/输入做法</th><th>核心实测结果</th><th>结论</th></tr></thead><tbody><tr><td><strong>音频前端软蒸馏</strong></td><td>1,024 条真转写 + 原生教师分布，训 128 步听入前端</td><td>48 条听写编辑数从 <code>840</code> 降至 <code>222</code>，但自然四问直接切题仍 <strong><code>0/4</code></strong></td><td>听写降错未转化为自主回答能力</td></tr><tr><td><strong>小样本多轨正文微调</strong></td><td>冻结底座，拿真人双轨原声微调正文（从 4 条扩至 18 条）</td><td>5 道开发题切题数始终 <strong><code>1/5</code></strong>；另一组正文残差留出 NLL 从 <code>4.82</code> 崩至 <code>15.80</code></td><td>缺规模化签名答文金标时，小样微调必飘移</td></tr><tr><td><strong>冻结底座 + 因果文字账本</strong></td><td><strong>不做任何正文微调</strong>，仅输入零起双路实时因果 ASR 文字 + 播放账本</td><td>MagicData <strong><code>5/5</code></strong>、跨语料 AliMeeting <strong><code>6/7</code></strong>（纯双轨原声 <code>3/7</code>，原声+文字 <code>2/7</code>）</td><td>30B 底座本身具备理解力，缺的是时间对齐的可读上下文</td></tr></tbody></table><p>更值得玩味的是“纯双轨原声 <code>3/7</code>、原声+文字反而退回 <code>2/7</code>”这一现象：在没有针对多轨连续输入重新对齐的条件下，原始长音频流与提示模板之间存在模态干扰；先把内容层锚定在经过严格时间对齐的文本因果流与 <code>ExecutionLedger</code> 上，反而能最稳地保住语义切题率。</p><h3 id="_3-3-混入高重叠抢话扩池的负收益" tabindex="-1">3.3 混入高重叠抢话扩池的负收益 <a class="header-anchor" href="#_3-3-混入高重叠抢话扩池的负收益" aria-label="Permalink to &quot;3.3 混入高重叠抢话扩池的负收益&quot;">​</a></h3><p>在主线框架跑通后，我们曾尝试从开源多轨池扩充训练正例，把包含三人高重叠交谈（重叠比例约 <code>21.7%</code>）和未经串音过滤的对话片段直接当作 <code>SE</code>（开始说话）正样本训进 SFT 与 GRPO。结果模型学出了严重的抢话倾向：<code>SmoothConv</code> 留出集上的说话期误抢率 <code>vir_rate</code> 飙升至 <strong><code>40.44%</code></strong>，<code>EOT-Bench zh</code> 的 <code>AUROC</code> 从 <code>0.9422</code> 跌至 <strong><code>0.8103</code></strong>。</p><p>全双工数据清洗里，把“人类抢麦插话”的时刻标注成“助手应当开口”的监督信号，破坏性远大于样本量不足。</p><h2 id="四、主线架构-80ms-同流状态机与亚秒级系统实装" tabindex="-1">四、主线架构：80ms 同流状态机与亚秒级系统实装 <a class="header-anchor" href="#四、主线架构-80ms-同流状态机与亚秒级系统实装" aria-label="Permalink to &quot;四、主线架构：80ms 同流状态机与亚秒级系统实装&quot;">​</a></h2><p>踩完上述几条岔路后，系统主线正式收敛为一套控制与内容分层的全双工架构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Mic 16k PCM] -&gt; AEC (NLMS) -&gt; Voiceprint Lock</span></span>
<span class="line"><span>                       │</span></span>
<span class="line"><span>                       ▼ (80ms Mimi 帧流)</span></span>
<span class="line"><span>[GPU 0 · 实时控制路径]</span></span>
<span class="line"><span>  StreamingEncoder + Control Thinker</span></span>
<span class="line"><span>  (17 控制词元 + FSM 掩码 + 因果确认门控)</span></span>
<span class="line"><span>    ├─ PAD : 异步推进 GPU 1 增量 KV 预填</span></span>
<span class="line"><span>    ├─ SE  : 连对 c2/c3 帧 -&gt; 触发 GPU 1 首词发声</span></span>
<span class="line"><span>    └─ SS  : 单帧立停 Talker -&gt; 回写已播字数账本</span></span>
<span class="line"><span>                       │</span></span>
<span class="line"><span>                       ▼</span></span>
<span class="line"><span>[GPU 1 · 内容生成路径]</span></span>
<span class="line"><span>  Frozen 30B Content Thinker (Sparse MoE)</span></span>
<span class="line"><span>  完整双路因果 ASR + ExecutionLedger 账本</span></span></code></pre></div><h3 id="_4-1-控制流的三个关键设计" tabindex="-1">4.1 控制流的三个关键设计 <a class="header-anchor" href="#_4-1-控制流的三个关键设计" aria-label="Permalink to &quot;4.1 控制流的三个关键设计&quot;">​</a></h3><ol><li><p><strong>80ms 同流 FSM 原语与分层学习率</strong> 借鉴 Awaken 的时间节拍，控制流以每帧 <code>80 ms</code> 步进，在 Thinker 词表内引入 17 个控制与边界词元（包括开始说话 <code>SE</code>、在播让出 <code>SS</code>、持续监听 <code>PAD</code> 以及不同长度的句中停顿词元 <code>pause_m</code>），并用有限状态机掩码（FSM）把每一步的合法词元转移锁死，消除非法状态跳变。 训练上通过消融定位出两个核心开关：仅训练 LoRA 时音频前端冻结导致跨会话 <code>SE</code> 召回归零，必须放开 <code>codes_to_uemb + fuse</code>；但前端学习率若不压低，会把 30B 的中文声学-语义先验打乱、导致回答吐出乱码。将音频前端学习率缩放到 <code>0.25x</code> 并使用干净双声道池（<code>SmoothConv</code> 隔离会话 + <code>MagicData-RAMC</code> + <code>AISHELL-4</code> 远场旁听负例）后，中文答文恢复到 <code>12/12</code> 流畅切题。</p></li><li><p><strong>控制词元专属 GRPO + 纯因果确认门控</strong> 在把核心动作基率拉离零点之后，我们做了一轮 4 卡控制词元专属 GRPO：策略梯度严格限制在控制与时序边界词元上，正文位置保留参考模型 KL 惩罚与 SFT 锚定损失（防止为刷时序分而截断回答）。单帧评估下，<code>SmoothConv</code> 召回跳升到 <code>64.22%</code>，但随之而来的是 <code>EOT-Bench zh</code> 上高达 <strong><code>140</code> 条早抢</strong>（其中 <code>83</code> 条集中爆发在 <code>200ms–5s</code> 的句中换气停顿里）。 解决句中气口误抢并不需要推翻 30B 注意力或外挂外部 VAD。我们在解码侧引入<strong>纯因果多帧确认门控</strong>：<code>SE</code> 需要连续 2–3 帧（<code>160–240 ms</code>）越过门限才允许开口，而打断让轮 <code>SS</code> 依然保持 1 帧（<code>80 ms</code>）即时响应。仅这一项纯因果解码门控，就把 <code>EOT-Bench</code> 总早抢从 <code>140</code> 条砍到了 <code>44</code> 条（<code>-68.6%</code>），说话期误抢 <code>vir_rate</code> 从 <code>37.92%</code> 压到 <code>10.12%</code>。</p></li><li><p><strong>修复校准窗口偏差</strong> 早期调工作点时使用了对称窗口 <code>[-12, +12]</code> 帧（即句末前后各 <code>960 ms</code>），无意中把大量用户还没说完时的抢跑当成了正命中。改为非对称因果窗 <code>[-4, +12]</code> 并配合长静默负例与平坦度约束后，锁定了主线工作点 <code>Plan A (-0.12, 0.5, c3)</code>，将 <code>SmoothConv</code> 上的 <code>vir_rate</code> 进一步压到了 <code>5.69%</code>，<code>EOT-Bench</code> 早抢压到 <code>31</code> 条。</p></li></ol><h3 id="_4-2-stage-4-破秒与-stage-5-完整拼图" tabindex="-1">4.2 Stage 4 破秒与 Stage 5 完整拼图 <a class="header-anchor" href="#_4-2-stage-4-破秒与-stage-5-完整拼图" aria-label="Permalink to &quot;4.2 Stage 4 破秒与 Stage 5 完整拼图&quot;">​</a></h3><p>模型能做决定还不够，真机开麦里只要卡顿超过一秒，交互感就会碎掉。工程侧分两步补齐了实时链路：</p><ul><li><strong>双卡解耦与异步增量 KV（Stage 4）</strong>：把实时监听/发声（GPU 0）和 30B 内容生成（GPU 1）彻底拆卡；在监听态 <code>PAD</code> 期间后台异步推进完整双路 ASR 与账本的 <code>DynamicCache</code> 增量预填，在候选句末连续命中即预备首词生成，同时在内容侧解包零化控制 LoRA 并启用稀疏 MoE 优化。配对实测下，同触发帧的 <code>TTFT</code>（首词延迟）从 <code>479.14 ms</code> 降至 <strong><code>52.39 ms</code></strong>（<code>9.15x</code> 提速，最大 <code>59.36 ms</code>），真实帧时钟的 <code>TTFA</code>（首包音频延迟）从 <code>1,769.04 ms</code> 降至 <strong><code>412.94 ms</code></strong>（<code>4.28x</code>）。在“请继续”断点测试中，首轮播完 26 个字遇到插话时零样本泄漏立停，次轮从第 27 个字精准续接。（不过在 <code>2,800</code> 帧长程压测里，单步帧耗 <code>p50</code> 为 <code>89.24 ms</code>，略超 <code>80 ms</code> 实时线，长程调度仍有待优化。）</li><li><strong>端云回声消除与正主声纹锁（Stage 5 拼图 1）</strong>：服务端 <code>AdaptivePlaybackAEC</code>（频域分块 NLMS + 三频段后滤波）每帧仅耗 <code>0.657 ms</code> CPU，实测获得 <strong><code>37.64 dB</code> 的回声抑制比（ERLE）</strong>；叠加首轮自动注册的 <code>WeSpeaker34</code> 正主声纹锁（均摊 <code>1.80 ms/帧</code>），将 <code>HumDial</code> 旁人后置发言拒识率从 <code>22.00%</code> 提到 <code>48.00%</code>，“正主接话 + 旁人拒识”联合通过率提升 <code>17.5x</code>（<code>1.33% → 23.33%</code>），在播期间旁人闲聊造成的误停播率从 <code>100.00%</code> 压降至 <code>36.25%</code>。</li><li><strong>1.47M 声学×词面联合控制头（Stage 5 拼图 2）</strong>：纯声学流很难区分“我在想问题（句中停顿）”和“我问完了（句末）”。在 100% 冻结 <code>Plan A</code> 声学底座的前提下，我们只用纯真人 <code>Easy-Turn</code> 训练集和干净负例训了一个 <code>1,472,537</code> 参数的声学×实时中文词面联合头，单帧 GPU 增量仅 <strong><code>p90 = 2.63–2.85 ms</code></strong>。它在 <code>Easy-Turn 400</code> 纯真人盲测上把四类判别全面拉高：<code>incomplete</code> 保持率 <code>31.33% → 56.67%</code>、<code>backchannel</code> 保持率 <code>58.00% → 92.00%</code>、<code>wait</code> 静默率 <code>0.00% → 18.00%</code>、<code>AUROC</code> 从 <code>0.5287</code> 跳升至 <strong><code>0.6945</code></strong>；同时把 <code>HumDial ask</code> 召回从 <code>66.33%</code> 拉回到 <code>81.33%</code>。</li></ul><h2 id="五、一次刺破-假繁荣-的全面审计-11-月-24–25-日" tabindex="-1">五、一次刺破“假繁荣”的全面审计（11 月 24–25 日） <a class="header-anchor" href="#五、一次刺破-假繁荣-的全面审计-11-月-24–25-日" aria-label="Permalink to &quot;五、一次刺破“假繁荣”的全面审计（11 月 24–25 日）&quot;">​</a></h2><p>到这里，系统看起来已经形成了一套工程闭环。但在最终验收前，一次对照原始 JSON 日志和评测代码的审计，把原本乐观的结论翻了出来。</p><h3 id="_5-1-审计揭露的三个真相" tabindex="-1">5.1 审计揭露的三个真相 <a class="header-anchor" href="#_5-1-审计揭露的三个真相" aria-label="Permalink to &quot;5.1 审计揭露的三个真相&quot;">​</a></h3><ol><li><p><strong>对称窗口掩盖了大量句末前抢跑</strong> 当把 <code>SmoothConv heldout</code> 的匹配规则从旧口径 <code>±960 ms</code> 收紧到<strong>严格句末后 <code>[0, +960 ms]</code></strong> 时，<code>Plan A (-0.12, 0.5, c3)</code> 的指标从 <code>P=30.60% / R=45.83% / F1=36.70%</code> 跌落到 <strong><code>P=20.93% / R=31.35% / F1=25.10%</code></strong>。全部 <code>879</code> 次开口预测里，有 <strong><code>695</code> 次</strong>其实发生在说话人还没说完之前。</p></li><li><p><strong>纯声学训练并没有提高阈值无关分辨力</strong> 对比完整基准结果发现，官方原版底座在 <code>EOT-Bench zh</code> 上的 <code>AUROC(all)</code> 本来就有 <strong><code>0.9421</code></strong>，而 <code>Plan A</code> 反而降到了 <strong><code>0.9364</code></strong>（<code>clean_eot</code> 从 <code>68.90%</code> 降到 <code>60.47%</code>）。 这轮纯声学 SFT + GRPO 真实改变的并不是“把句末和停顿分得更开”，而是把全局 <code>pad_acc</code> 从原生 <code>0.9118</code>（<code>Clean-SFT</code> 为 <code>0.9800</code>）压低到了 <strong><code>0.8193</code></strong>。模型变得极易开口（长段输入里的句中早抢在 <code>MagicData_5</code> 上从 <code>148</code> 次暴增到 <code>712</code> 次），再依靠 <code>-0.12</code> 负偏置与 3 帧确认把误触发强行摁回来。一压一抬之间，直接造成了多项首问能力退步：<code>HumDial ask</code> 从 <code>99.33%</code> 掉到 <code>66.33%</code>（挂联合头后恢复到 <code>81.33%</code>），<code>Full-Duplex-Bench</code> 顺畅接话从 <code>78.15%</code> 掉到 <code>68.91%</code>，<code>Addressee v1</code> 退化为全静默。</p></li><li><p><strong>三条曾经掩盖问题的评测脚本 Bug</strong></p><ul><li><strong>首轮漏答伪装成“零残留”</strong>：真实打断换题用例里模型第一轮压根没开口（<code>first_se_frame = null</code>），旧脚本却将其记为旧音残留 <code>0</code> 帧；修复判定后，真实暴露出 <code>Plan A (-0.12)</code> 在该用例首轮漏答。</li><li><strong>LoRA 清零不彻底</strong>：<code>Speech-CMMLU</code> 消融脚本按 <code>.lora_</code> 子串清零参数，漏掉了 <code>.A.weight</code> / <code>.B.weight</code> 共 <code>384</code> 个适配器张量；改为按模块类型精确清零后，才确认控制微调与原生基座在纯客观问答上确实无损打平（<code>81.17%</code> vs <code>81.33%</code>，<code>Δ=0.00%</code>）。</li><li><strong>打断延迟亚帧伪影</strong>：部分评测对用户开口切点直接减帧起点，算出低于 <code>80 ms</code> 帧长的虚假停播延迟，改用 <code>math.ceil</code> 帧对齐后方恢复物理真实性。</li></ul></li></ol><h3 id="_5-2-三组归因对照把功劳拆清" tabindex="-1">5.2 三组归因对照把功劳拆清 <a class="header-anchor" href="#_5-2-三组归因对照把功劳拆清" aria-label="Permalink to &quot;5.2 三组归因对照把功劳拆清&quot;">​</a></h3><p>为了彻底剥离“训练收益”“后处理门控收益”和“词面特征收益”，除了修复评测脚本后重测 <code>Plan A (-0.12)</code> 本身，我们在 11 月 25 日还跑了三组受控归因对照实验：</p><table tabindex="0"><thead><tr><th>对照问题</th><th>核心对比结果</th><th>剥离出的真实结论</th></tr></thead><tbody><tr><td><strong>1. 官方原版 + 同等校准门控能走多远？</strong></td><td>原版 <code>Baseline</code> 加 <code>ss_bias=1.0</code> 后，<code>HumDial</code> 4 类打断 1s 让出率也从 <code>97.0%</code>（<code>0.378s</code>）升至 <code>100.0%</code>（<code>0.190s</code>）；但流式双通道语音探针里，原版 <code>98.53%–100%</code> 漂移为英文输出，<code>pause</code> 误抢高达 <code>80.00%</code></td><td>打断灵敏度部分来自 <code>ss_bias</code> 门控；中文对齐与 <code>pause</code> 误抢抑制（<code>80% → 24%</code>）来自微调与中文底座</td></tr><tr><td><strong>2. 等预算下 GRPO vs 继续 SFT 谁更值？</strong></td><td>同起点 <code>Clean-SFT</code>（<code>0.2003</code>）各续训 <code>~1.05</code> PPU·h：继续 SFT 使开发集 <code>vir_rate</code> 翻倍（<code>5.24% → 12.35%</code>）、长负例误报升至 <code>75.86%</code>；3 步 GRPO 将长负例误报压至 <code>60.34%</code>、短误触降至 <code>1.65%</code>（综合分 <code>0.1954</code>）</td><td>继续恢复 SFT 容易推高抢话；极小预算 GRPO 抑制误触更干净，但策略偏保守</td></tr><tr><td><strong>3. 联合头收益是靠中文词面，还是靠同分布数据？</strong></td><td>在完全相同的 <code>Easy-Turn + 干净负例</code> 特征上屏蔽词面只训纯声学头：<code>AUROC</code> 升至 <code>0.6059</code>、<code>wait</code> 升至 <code>56%</code>，但 <code>complete</code> 召回跌到 <code>53.33%</code>；接入实时词面后，<code>complete</code> 稳在 <code>72.67%</code> 且 <code>AUROC</code> 达到 <code>0.6945</code>（<code>backchannel</code> <code>92%</code>）</td><td>同分布数据本身能抬升 <code>wait</code> 与拒识，但<strong>只有加入词面语义才能在不牺牲首问召回的前提下分离句中停顿与附和</strong></td></tr></tbody></table><p>把这些对照组放在一起，新立项的 <code>Plan D v2</code> 方向就明确了：<strong>100% 冻结音频前端 <code>fe/proj</code>，用成对排序 Margin Loss 直接优化阈值无关 <code>AUROC</code></strong>。在已完成的首轮 300 步训练与严格后验 <code>[0, +12]</code> 帧扫描中，<code>Plan D v2</code> 已将校验集 <code>se_vs_pad_auroc</code> 从起始 <code>0.8612</code> 推高到 <strong><code>0.9786</code></strong>（<code>neg_wait_fp_rate = 0.0</code>、<code>pad_acc = 0.9194</code>），严格后验校准扫描 <code>vir_rate</code> 压低至 <code>1.74%–2.17%</code>（完整留出与跨基准大考仍在进行中）。</p><h2 id="六、如果从零重训-集齐全部优化手段的完整训练配方" tabindex="-1">六、如果从零重训：集齐全部优化手段的完整训练配方 <a class="header-anchor" href="#六、如果从零重训-集齐全部优化手段的完整训练配方" aria-label="Permalink to &quot;六、如果从零重训：集齐全部优化手段的完整训练配方&quot;">​</a></h2><p>如果今天把这十天验证过的全部有效手段一次装齐、绕开所有已知陷阱，重新从零训练一版中文全双工模型，应该按下面这条端到端流水线推进。</p><h3 id="_6-1-现实算力版-4–8-卡可复现的全优化配方" tabindex="-1">6.1 现实算力版（4–8 卡可复现的全优化配方） <a class="header-anchor" href="#_6-1-现实算力版-4–8-卡可复现的全优化配方" aria-label="Permalink to &quot;6.1 现实算力版（4–8 卡可复现的全优化配方）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Phase 0 · 数据去毒分流 (0 卡 CPU)</span></span>
<span class="line"><span>  正例: 仅取零串音双声道 -&gt; 编为 80ms Mimi + 17 词元 FSM</span></span>
<span class="line"><span>  负例: 全量远场旁听 + 高重叠(pad_ss_only) + 真半句 + 账本扰动</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>Phase 1 · 工程闸门 (单卡 Smoke -&gt; 多卡等价)</span></span>
<span class="line"><span>  scene_forward 流式等价 -&gt; save/restore 逐位一致 -&gt; 拟合门</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>Phase 2 · 冻结前端排序 SFT (核心声学底座)</span></span>
<span class="line"><span>  100% 冻结 fe/proj + q/k/v/o LoRA + 17 词元</span></span>
<span class="line"><span>  Loss = 加权 CE + 内容 KL 锚 + [0,+3] 窗口 + Pairwise AUROC</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>Phase 3 · 门禁后动作级 GRPO (AUROC 超基座后启用)</span></span>
<span class="line"><span>  冻 fe/proj + 控制词元 PG + c2/c3 对齐 + 1:1 恢复 SFT 对照</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>Phase 4 · 冻结主干挂接词面联合头 &amp; 声学护栏</span></span>
<span class="line"><span>  1.47M 声学×实时中文词面头 (p90 &lt; 3ms) + AEC + WeSpeaker34</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>Phase 5 · 严格 [0,+12] 守门员校准 &amp; 双卡亚秒部署</span></span>
<span class="line"><span>  calib+dev+dev_neg 锁点 -&gt; GPU0 控制发声 + GPU1 增量 KV</span></span></code></pre></div><p>每一阶段的具体做法与不可妥协的防线如下：</p><ol><li><p><strong>Phase 0｜数据去毒分流与零泄漏编帧</strong></p><ul><li><strong>正负例严格物理分流</strong>：<code>SE</code>（开口）正例只取经串音审计的严格单人双声道（例如 <code>SmoothConv _2ch</code> 隔离会话，并要求 <code>true_se</code> 前留足净音缓冲），<strong>绝对不把未筛重叠的多人抢话标成 <code>SE</code> 正例</strong>。</li><li><strong>充分利用高重叠与旁听负例</strong>：将 <code>AISHELL-4</code> 远场旁听、<code>Basis</code> 三人高重叠对话、未完半句与长静默全部以 <code>pad_ss_only</code> 模式入池——屏蔽 <code>SE</code> 损失，单向训练“别人在说/旁人闲聊时保持 <code>PAD</code>”与“自己在播遇插话时立刻 <code>SS</code>”。</li><li><strong>历史扰动与零污染隔离</strong>：混入少量真实设备 <code>ExecutionLedger</code> 扰动样本（未播追问、部分已播断点）；按完整会话和说话人切分 <code>train / calib / dev / heldout</code>，严禁任何外部评测集与 TTS 合成音频混入。</li></ul></li><li><p><strong>Phase 1｜先过工程等价与训练集拟合门</strong></p><ul><li><strong>加速前先验等价</strong>：训练前向采用单次整场多截点因果前向（<code>scene_forward</code> 思路），先在 BF16 下完成与逐帧流式打分的分数排序等价核验；多卡扩量前必须对同一样本与有效批量验证 1 卡 vs 多卡的梯度和一步更新等价，防止 BF16 DDP 数值静默漂移。</li><li><strong>2 步 Smoke 与拟合门</strong>：正式长训前必跑 2 步 smoke（验证 <code>save</code>/<code>restore</code> 逐位一致且评测脚本可真实跑通）；任何新配方先在小集上过训练集拟合门，避免把欠拟合误判成路线失败。</li></ul></li><li><p><strong>Phase 2｜冻结音频前端的去毒排序 SFT（替代旧版放开前端 SFT）</strong></p><ul><li><strong>参数冻结边界</strong>：<strong>从 SFT 第一步就 100% 冻结音频前端 <code>fe/proj</code>（<code>codes_to_uemb + fuse</code>）、30B 主干与 Talker</strong>，只开放 Thinker 注意力层 <code>q/k/v/o</code> LoRA（不包 MoE 专家 FFN）及 17 个控制词元的输入嵌入与输出行。这是守住 <code>pad_acc &gt;= 0.92</code>、防止中文先验漂移与首问退步的根本护栏。</li><li><strong>四项复合目标</strong>： <ul><li><strong>类别加权 CE + 强内容 KL 锚（<code>kl_beta ≈ 0.30</code>）</strong>：对说话期 <code>PAD</code>（<code>1.6x</code>）、句中语义悬停 <code>PAD</code>（<code>1.8x</code>）和长尾停顿词元（<code>3.0x</code>）显式加权，参考模型锁死正文分布防止语义退化；</li><li><strong>严格句末后 First-Passage 窗口似然（<code>win_left=0, win_right=3</code>）</strong>：只把 <code>[0, +240ms]</code> 句末后窗口计为合法开口区间（彻底去掉 <code>win_left &gt; 0</code> 的提前奖励），同时开启 <code>zero_overlap_se</code> 屏蔽存在人声交叠帧的 <code>SE</code> 监督；</li><li><strong>平移不变的成对排序 Loss（<code>Pairwise AUROC Margin</code>, <code>margin=2.2</code>, <code>weight=0.60</code>）</strong>：在每一段音频内取干净句末 <code>SE</code> 帧与 Top-k 最难的句中停顿/人声 <code>PAD</code> 帧计算 <code>softplus(margin - (m_pos - m_neg))</code>，并用跨片段 EMA 边界桥接把纯负例半句和干净正例拉到同一标尺上，直接优化阈值无关 <code>AUROC</code>。</li></ul></li></ul></li><li><p><strong>Phase 3｜带硬门禁的动作级 GRPO（不盲目上 RL）</strong></p><ul><li><strong>准入硬门槛</strong>：只有当 Phase 2 的 SFT 底座在独立验证集上做到 <code>EOT-Bench AUROC</code> 实质超越官方原版且首问召回不退步时，才进入 GRPO。</li><li><strong>训练/推理同构与防 Hack</strong>：全程继续冻结 <code>fe/proj</code>，策略梯度严格限定在控制与时序词元，正文保留 <code>sft_anchor + kl_beta</code> 硬约束；rollout 阶段直接挂载部署态的 <code>c2/c3</code> 多帧因果确认门控，把句中停顿误抢惩罚（<code>semantic_hold_fp_pen</code>）和打断延迟写进因子化奖励。必须与同等卡时的恢复 SFT 做 1:1 盲评对照，只在严格 <code>[0, +960ms]</code> 指标上净胜时才替换底座。</li></ul></li><li><p><strong>Phase 4｜冻结声学底座，外挂轻量词面联合头与前端护栏</strong></p><ul><li><strong>为什么不在主干硬塞词面</strong>：控制主干负责 80ms 级声学节奏与即时打断，词面语义判断交给外挂的 <code>~1.5M</code> 轻量联合头（<code>p90 &lt; 3 ms/帧</code>），100% 冻结声学主干，避免破坏已校准好的声学边界。</li><li><strong>数据与护栏</strong>：联合头只用纯真人 <code>Easy-Turn</code> 训练集与干净负例训练，重点拉开「说完 / 未完半句 / 附和 / 要求等待」四类；前端叠加频域分块 NLMS 回声消除（<code>ERLE ~37.6 dB</code>）与首轮正主 <code>WeSpeaker34</code> 声纹锁，补齐公放防自激与多人场景旁人拒识。</li></ul></li><li><p><strong>Phase 5｜严格后验守门员校准与亚秒级部署</strong></p><ul><li><strong>校准铁律</strong>：只在隔离的 <code>calib + dev + dev_neg</code> 上以<strong>严格句末后 <code>[0, +12]</code> 帧（<code>[0, +960ms]</code>）+ 邻域平坦度</strong>锁定 <code>(se_bias, ss_bias, confirm)</code>，严禁使用对称窗口或偷看测试集；<code>SS</code> 保持 1 帧即时让出。</li><li><strong>亚秒级运行时</strong>：控制 Thinker 与 Talker 驻留 GPU 0，冻结原生 30B 内容 Thinker 驻留 GPU 1；监听态 <code>PAD</code> 期间异步增量推进完整双路 ASR 与 <code>ExecutionLedger</code> 的 <code>DynamicCache</code> 预填，内容侧解包零化控制 LoRA 并启用稀疏 MoE；上线同时配套 20 秒滚动环形缓冲的错题飞轮，持续收集真实真机失败轨迹回流迭代。</li></ul></li></ol><h3 id="_6-2-如果算力充裕-终局形态怎么升级" tabindex="-1">6.2 如果算力充裕：终局形态怎么升级 <a class="header-anchor" href="#_6-2-如果算力充裕-终局形态怎么升级" aria-label="Permalink to &quot;6.2 如果算力充裕：终局形态怎么升级&quot;">​</a></h3><p>上面这套配方里的三处妥协——用“冻结主干 + LoRA”替代全参对齐、用“静态 SFT + 窗口似然 + 局部扰动”替代全序列自回归 rollout、短期仍需少量静态 logits 偏置过渡——本质上都是受限于单双卡/小集群算力的工程折中。</p><p>如果算力充裕，架构骨架（完整因果前缀 + 同流 FSM 原语 + 动作/内容解耦 + 真实播放账本）依然不需要推翻，真正值得升级的是三件事：一是做<strong>全参视听文流式联合对齐</strong>（把音频编码塔彻底流式化，避免冻结编码塔在输入层锁死分布漂移）；二是在训练期引入<strong>真 Free-Running Rollout</strong>（借鉴 Duo Stage 3，让模型在训练时直接吃自己自回归生成的语音、动作与播放状态，消除曝光偏差，从而彻底扔掉静态偏置补丁）；三是在完整因果前缀上生长出<strong>可学习的长期记忆压缩与异步后台推理</strong>，既保住长程一致性，又突破长会话单步延迟随上下文线性增长的上限。</p><h3 id="_6-3-带走的三条经验" tabindex="-1">6.3 带走的三条经验 <a class="header-anchor" href="#_6-3-带走的三条经验" aria-label="Permalink to &quot;6.3 带走的三条经验&quot;">​</a></h3><ol><li><strong>先把评测窗口和归因拆干净，再为指标上涨高兴。</strong> 对称时间窗、未清零的 LoRA 张量、未触发首轮时的默认零残留、以及未过训练集拟合门下的负结论，全都会把方向带偏到几百卡时之外。</li><li><strong>动作和内容必须解耦优化，数据清洗永远优先于盲目扩池。</strong> 把高重叠抢话标成 <code>SE</code> 正例会直接污染零样本区分度；把说话时机和正文词混进无约束的 RL 奖励只会带来语言退化。</li><li><strong>对于复杂全双工对话，系统状态（<code>ExecutionLedger</code>）和语义上下文（双路因果 ASR + 词面头）不是“工程补丁”，而是决策底座的一部分。</strong> 仅靠声学端点只能分辨停顿的声学质感，分辨不出用户是不是在说“然后我当时就……”，也分辨不出助手上句话究竟有没有真正从扬声器播出来。</li></ol>`,58)])])}const u=o(n,[["render",a]]);export{h as __pageData,u as default};
